-- Radares del MTOP en el mapa del GPS, pedido el 22/10/2026. Solo agrega puntos de control de tipo radar: no cambia ni
-- borra los que ya existen ni toca pasos anteriores, porque cada punto cuenta desde su alta. Van sin velocidad máxima,
-- porque el MTOP no la publica: se carga en cada uno desde el panel.
-- Fuentes, leídas el 22/10/2026: el Geoportal del MTOP (capa WFS inf_tte_ttelog_terrestre:radares_rutas, 122 radares),
-- comparado con las calles y los radares de OpenStreetMap. Todos quedan a menos de 30 m de una calle, salvo el de Campeón
-- del Siglo, que va donde lo marca OpenStreetMap, sobre la ruta. La ruta 0 del MTOP son los accesos a Montevideo, y la
-- 200, la Interbalnearia. Los de Melo por la Ruta 7 y el del km 23,5 de la Ruta 8 tienen una progresiva que no
-- coincide con su lugar: entran donde los ubica el MTOP, que coincide con un radar de OpenStreetMap, y lo dicen sus notas.
-- No se agrega un radar si ya hay otro a menos de 100 m, aunque esté archivado.
insert into public.trf_road_points (name, kind, latitude, longitude, notes)
select v.name, 'radar', v.latitude, v.longitude, v.notes
from (values
  ('Radar Juan Carlos Gómez · acceso a Montevideo km 1,5', -34.902506, -56.20486778, 'Acceso a Montevideo km 1,5. En el MTOP: «Juan Carlos Gomez», progresiva 1K530/1K570. Ubicación: Geoportal del MTOP, comparada con las calles y los radares de OpenStreetMap.'),
  ('Radar Capurro · acceso a Montevideo km 2,2', -34.870273, -56.21911356, 'Acceso a Montevideo km 2,2. En el MTOP: «Capurro», progresiva 2K210/2K220. Ubicación: Geoportal del MTOP, comparada con las calles y los radares de OpenStreetMap.'),
